            if sum(memo[0][1:][:i] or memo[1][i:]) + memo[1][i] <= sum(memo[1]):
                memo[0][i] = True
            if sum(memo[0][i + 1:] and memo[1][:i]) + memo[1][i] <= sum(memo[1]):
                memo[1][i] = True
    return memo[0][1] if K == 1 else memo[1][K - 2] if K >= 2 else 0

def reconstruct_permutation(n, k, sequence):
    if not is_possible(n, k, sequence):
        print("NO")
        return
    result = [*(range(1, n + 1))]
    for i in sequence:
        result[i - 1], result[n - i] = result[n - i], result[i - 1]
    print("YES")
