    colors = {}
    for num in guess:
        if num in colors:
            colors[num] += 1
        else:
            colors[num] = 1

    if x * y > len(guess):
        return "NO"

    missing_indices = x - 1
    distinct_colors = len(guess)
    total_colors = len(colors)

    if distinct_colors == total_colors:
        return "YES"

    if x > 0 and (y - x <= distinct_colors or x == 1 and guess[0] in colors):
        return "YES"

    code = []

    for num, count in sorted(colors.items(), key=lambda item: item[1]):
        if count > 0 and (num in guess or total_colors > 1):
            code.append(num)
            guess.remove(num)
            count -= 1

        if missing_indices == 0:
            break

