        operations = []
        for _ in range(m):
            t = int(input())
            if t == 1:
                li, ri, xi = map(int, input().split())
                operations.append((li, ri, xi, 'max'))
            elif t == 2:
                ki, di = map(int, input().split())
                operations.append((ki - 1, ki - 1, di, 'set'))

        return n, m, operations

    n, m, operations = parse_input()

    if m * 3 + n < sys.getsizeof(map(int)) or m * 3 + n > sys.getsizeof(list(int() for _ in range(n))):
        raise ValueError("input size exceeds memory limit")

    operations = sorted(operations, key=lambda x: x[0])

    max_heap = []
    cuteness = []
    all_integers = set()

    for i in range(n):
        all_integers.add((i, 0))

    for type_4, _, xi, _ in operations:

        if type_4 == 'max':
            li, ri, xi, _ = operations[type_4 - 1]
            max_integers = set()
            for li_, ri_ in all_integers:
                if li <= li_ <= ri_ <= ri:
                    max_integers.add(xi & 0xffffffff)  # Compute OR result and filter out max values within the range

            flashlight = []
            for xi in max_integers:
                heapq.heappush(flashlight, (xi >> 32, xi))

            heap = max_heap
            for heap_size, heap_val in flashlight:
                for li, ri, xi in all_integers:
                    if li <= heap:
                        heap_val = heap_val & xi & 0xffffffff  # Compute OR result and filter out max values within the range
                        if heap_val != heap: break
                        heapq.heappop(heap)
                        heapq.heappush(heap, (heap_val >> 32, heap_val))

            flashlight.clear()
            for zipped in heapq.nlargest(len(heap), max_heap.items()):
                flashlight.append(zipped)

            for zipped, heap_val in flashlight:
                cuteness.append(heap_val & 0xffffffff)

        elif type_4 == 'set':
            ki, di, _ = operations[type_4 - 1]
            new_integer = set()

            for li, ri in all_integers:
                if li <= ki <= ri:
                    new_integer.add((ki - 1, (di << 32)))

            for li, ri, xi in all_integers:
                if ki - 1 <= li and ki - 1 <= ri:
                    new_integer.discard((li, xi))
                    new_integer.discard((ri, xi))

            for li, ri in new_integer:
                all_integers.add((li, xi))
                all_integers.add((ri, xi))

        all_integers = set()

    result = sorted(zip(cuteness, all_integers))
