@lru_cache(None)
def dp(i, flag):
    if i == N:
        return 1
    result = flags[i] * dp(i + 1, 0) + dp(i + 1, 1)
    for s in range(2):
        j = i
        while j > N - i - 1 and not flags[j]:
            j += gen(j)
        flags[j] = 0
        while j >= N - i - 1 and flags[j] == s:
            j -= gen(j)
        if flags[j] == s:
            while j > i and flag:
                j -= gen(j)
            result += dp(j + 1, s) & 0xffffffff
        j += gen(i)
        flags[j] = 0
        while j >= i and flags[j] == s:
            j -= gen(j)
        if flags[j] == s:
            while j > i + 1 and flag:
                j -= gen(j)
            result += dp(j + 1, s) & 0xffffffff
    return result % (10**9 + 7)

@lru_cache(None)
def gen(pre):
    if pre == i:
        return 1
    if pre & 1:  # even
        gen = [min(gen(pre + 1), gen(pre - 1)) for _ in range(N)]
    else:  # odd
        left = gen(pre)[1::2][::-1]
        left = [min(a - b, 2) for a in gen if a >= 2 for b in reversed(left)]
        right = [min(left[a], a - 1) if a < 1 else left[a - 1] for a in range(N - 1, 0, -1)]
        gen = left + [0] + right
    return [gen[pre & 1] // 2 + (pre >> 1) % 2 for pre in range(N)][(pre >> 1) % 2]

