    n = len(a)
    remap_dict = defaultdict(list)
    remap = [0]*n
    for i in range(1, n-1):
        if a[i-1] != a[i+1]:
            remap[i] = 0
            remap_dict[a[i]].append(i)
    remap_dict[a[0]], remap_dict[a[n-1]] = [], []
    remap_dict[a[n-1]].append(n-1)
    return remap_dict

def flip_word(s):
    rev_s = ''.join(reversed(s))
    for i in range(1, len(s)):
        if s[i] != s[i-1]:
            return True
    return False

def find_min_to_empty(a, remap_dict):
