def f(x):
    """Compute the Fibonnaci number f(x) modulo 10^9+7"""
    if x == 0 or x == 1:
        return 1

    if memo[x] != 0:
        return memo[x]

    memo[x] = 1 + sum((f(x - i) * f(i) for i in range(1, x + 1))) % MOD
    return memo[x]


def dfs(index):
    """Recursively calculate the sum of f(sa|sb) * f(sc) * f(sd^se)"""
    if index == n:
        return 0

    ans = 0
    for j in range(index, n):
        s1 = s[index] | s[j]
        if (s1 & s[index] ^ s1) % 2 == 0:
            ans += (f(s1) * f(s[index]) * f(s[j])) % MOD

    return ans + dfs(index + 1)


