def can_construct_permutation(n, k, subseq):
    # Sort the subsequence in ascending order
    subseq.sort()

    # Check if the sorted subsequence is strictly decreasing
    if all(i > j for i, j in zip(subseq, subseq[1:])):
        return "NO"

    # If the largest element in the subsequence should come just before the next largest element
    if subseq[k-2] != subseq[k-1] - 1:
        return "NO"

    count = {}
    # Count occurrences of each number in the subsequence
    for num in subseq:
        count[num] = count.get(num, 0) + 1

    # Check that the largest subsequence size is <= n-1
    if count[subseq[k-1]] > n - 1:
        return "NO"

    # Check if any element can be moved to the end of parent element to form LIS
    for i in range(0, k-1):
        if count[subseq[i]] > 1 or subseq[i] + 1 != subseq[i+1]:
            return "NO"

    return "YES"

