        for b in range(1, sys.maxsize**0.5 + 1):
            if not is_square(b**2 % (10**8)):
                continue
            ra = (1 if a == 1 else sys.maxsize//a) * a
            rb = (1 if a == 1 else sys.maxsize//b) * b
            if not ra <= N < 1 + sys.maxsize//ra or not rb <= M < 1 + sys.maxsize//rb:
                continue
            sol = [a] * ra + [0] + [b] * rb
            if is_square(sa:=sum(sol[:ra*N])):
                col = 1
                for r in sol[ra*N:] + [0 for _ in range(col*(M - rb))]:
                    if not is_square(sum(r)):
