def min_balance_degree(n, m, k, changes):
    # Sort the indices in decreasing order
    sorted_indices = sorted([-1 * (peer - pos) for pos in changes] + [0])

    # Initialize variables to calculate the balance degree
    last_status = 0
    unique_changes = deque()
    repeat_changes_count = {}

    for i, status in enumerate(sorted_indices, start=1):
        if status < 0:
            change_id = -status
            if change_id in repeat_changes_count:
                repeat_changes_count[change_id] += 1
                last_status = -change_id
            else:
                repeat_changes_count[change_id] = 1
            n_changes = k + len(unique_changes) - 1
            while n_changes < 0:
                if n_changes + 1 <= len(set(unique_changes)):
                    repeat_changes_count[last_status] += len(set(unique_changes))
                    break
                n_changes -= 1
                last_status += 1
            if len(unique_changes) > 0 and last_status == 0:
                repeat_changes_count[len(set(unique_changes)) - 1] += 1
                for i in range(1, len(unique_changes) - 1):
                    last_status -= 1
        else:
            repeat_changes_count[0] += 1

    return max(i * fold for i, fold in zip(sorted_indices, unique_changes))

