            return "YES" + " ".join("1" * n)
        elif y == n + 1:
            return "YES" + " ".join("1" * x + "3" * (1 << n - x))
        elif n == x == y:
            return "YES" + " ".join("1" * x + "1" * n - x)
        elif y == 1 and x < n:
            return "YES" + " ".join("1" * (y + 1) + "4")
        elif x < 1 << n - y:
            return "YES" + " ".join("1" * max(x, n - y) + "2" * (1 << (n - max(x, n - y)) - x))
        else:
            if 3 <= n and 3 <= y * 2 <= n + 1 and 0 <= x * 2 <= y * 2 <= n:
                return "YES" + " ".join("1" * x + "3" * y)
            return "NO"

