from typing import List, Tuple

class ModularDataStructure:
    def __init__(self, values: List[int], frequencies: List[int]):
        self.values = values
        self.frequencies = frequencies
        self.modulo = 998244353

    def calculate_product(self) -> int:
        MOD_2 = MOD_4 = MOD_8 = MOD_16 = 3 ** 2
        MOD_18 = MOD_36 = 3 ** 2

        left_products = self.calc_right_modulo(-18)
        right_products = self.calc_right_modulo(18)

        return (left_products * right_products) % self.modulo

    def calc_right_modulo(self, modulo: int) -> int:
        right_products = [0] * (4 if modulo in {3, 9, 14} else 4 if modulo % 4 != 1 else (4 if modulo % 2 == 1 else 4 if modulo == 2 else 3))
        odd_mult = sum(f * 2 for f in self.frequencies).modPow(998244353 * 400300348, self.modulo) % self.modulo
        even_sum = sum(f * 2 ** (f - 1) for f in self.frequencies)
        even_sum = (odd_mult * even_sum) % self.modulo

        for i in range(2, len(right_products)):
            right_products[i] = (right_products[i - 2] * right_products[i - 2] % self.modulo + even_shifted(self.values, i, left_products, MOD_4)) % self.modulo

        return right_products[-1]

def odd_shifted(values: List[int], shift: int, left_products: List[int], modulo: int) -> int:
    right_products = [0] * (4 if modulo in {3, 9, 14} else 4 if modulo % 4 != 1 else (4 if modulo % 2 == 1 else 4 if modulo == 2 else 3))
    for i in range(min(len(values), shift), len(values) - shift + 1):
        right_products[i % 4] = (left_products[i % 2] * values[i % 2] + right_products[(i + 3) % 4]) % modulo

    return right_products[-1]

def even_shifted(values: Tuple[int, ...], shift: int, left_products: List[int], modulo: int) -> int:
    right_products = [0] * (4 if modulo in {3, 9, 14} else 4 if modulo % 4 != 1 else (4 if modulo % 2 == 1 else 4 if modulo == 2 else 3))
    for i in range(min(len(values), shift), len(values) - shift + 1):
        right_products[i % 4] = (left_products[i % 2] * values[i % 2] + right_products[(i + 3) % 4]) % modulo

    return right_products[-1] + 39916802 % modulo if modulo % 2 == 1 else (right_products[-1] + right_products[1]) % modulo

