def generate_square_sqr(N, mod):
    """Generate a square matrix and its QR decomposition, up to modulo"""
    Q, R = np.linalg.qr(np.pad((np.arange(N) % mod).reshape((N, 1)), (0, 1)))
    ai_for_j = 1.0 / Q[:, 1:2]
    ai_for_j = np.mod(ai_for_j / ai_for_j[Bound - 1], 1) * 1.0
    inv = dict()
    for k in range(N - 1):
        inv[k] = np.diagonal(R[k:, k])
    Ai_for_j = [np.vectorize(lambda x: ai_for_j[x // k])(np.arange(N))[None, :] for k in range(N)]
    aL_for_j = [np.linalg.solve(Ai_for_j[k] @ R[k, k:], np.empty(N)) for k in range(N - 2, -1, -1)]

    for k, inv_k in inv.items():
        yield np.empty(N, dtype=np.int), np.concatenate((Ai_for_j[k], inv_k, Q[:, -1].reshape(1)))
        for kk, invkk in inv.items():
            if kk > k:
                yield ai_for_j[kk] + inv_k, inv_kk + ai_for_j[kk]
            yield acl_for_j[kk] @ Q[k, :-1, None] @ raft[(k, kk)], inv_kk @ Q[(k, kk), -1]


@lru_cache(None)
def f(N):
    if N == 0:
        return 0
    elif N == 1:
        return 1
    res = 0
    for ai, inv in generated_square_sqr(N + 2):
        res += np.prod(inv) * fai((ai @ fai(ai) - ai ** 2) % (N + 2))
    return np.sum(res)
