def count_permutations(skill_levels):
    n = len(skill_levels)
    # Initialize the DP array where dp[i] is the number of ways to complete the sequence
    # if both have skill level 2 on the first look ahead
    dp = [[0 for _ in range(n)] for _ in range(n)]
    dp[0][0], dp[0][1] = 1, 1  # Base case when both neighbors have skill 2

    # Build the DP table
    for i in range(n):
        for j in range(n-i-1, min(i+2, n-1)):
            dp[j][j+1] = (dp[j][j+1] + check_last(j+1, 2, skill_levels, dp, n-i)) % (10**9 + 7)

    return sum(dp[-1]) % (10**9 + 7)

def check_last(j, current, skill_levels, dp, n):
    if current == 2:
        return dp[(n-j-1)][j] * current % (10**9 + 7)
    elif j == 0:
        return 0
    else:
        return dp[(n-j-1)][j] * (current * 1 + current * -1) % (10**9 + 7)

