    for start in range(n + 1):
        for end in range(start, n + 1):
            if end - start >= 2 and (original_sequence[start] or original_sequence[end - 1]):
                results.discard(binarize_value(original_sequence[start: end + 1]))

    unique_sequences = sorted(results, key=lambda x: x)
    if not unique_sequences:
        return "NO"

    shortest_sequence = None
    longest_sequence = None
    longest_cuteness = 0

    for sequence in unique_sequences:
        cuteness = binarize_value(sequence)
        if longest_sequence is None or cuteness > longest_cuteness:
            longest_sequence = sequence
            longest_cuteness = cuteness

    if longest_sequence is None:
        return "NO"

    return "YES\n" + " ".join(map(str, longest_sequence))

