def count_possible_outcomes(n, skills):
    modulo = 10**9 + 7
    dp = [0] * n
    dp[0] = 1  # Dog 1 always receives the ball
    for i in range(1, n):
        dp[i] = dp[i - 1]
        for s in range(1, skills[i]):
